def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        sites = s.get('sites') or []
        n = sum(max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites)
        volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
        v = volume / n if n > 0 else 0.0
    return float(log(v)) if v > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    occupied = 0.0
    spheres = 0.0
    for t in sites:
        o = max(0.0, float(t.get('occupancy', 1.0) or 0.0))
        p = props.get(t.get('element')) or {}
        r = p.get('covalent_radius_A') or p.get('atomic_radius_A') or 1.4
        occupied += o
        spheres += o * max(0.0, r) ** 3
    volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
    if volume <= 0:
        volume = (s.get('volume_per_atom_A3') or 0.0) * occupied
    return float(4.0 * pi * spheres / (3.0 * volume)) if volume > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = []
    occ = []
    for t in sites:
        p = props.get(t.get('element')) or {}
        radii.append(max(0.1, p.get('covalent_radius_A') or p.get('atomic_radius_A') or 1.4))
        occ.append(max(0.0, float(t.get('occupancy', 1.0) or 0.0)))
    nearest = [inf for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d / (radii[i] + radii[j]))
    total = sum(occ[i] for i in range(n) if nearest[i] < inf)
    return float(sum(occ[i] * nearest[i] for i in range(n) if nearest[i] < inf) / total) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = []
    occ = []
    for t in sites:
        p = props.get(t.get('element')) or {}
        radii.append(max(0.1, p.get('covalent_radius_A') or p.get('atomic_radius_A') or 1.4))
        occ.append(max(0.0, float(t.get('occupancy', 1.0) or 0.0)))
    total = sum(occ)
    penalty = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0:
            x = d / (radii[i] + radii[j])
            if x < 1.0:
                penalty += occ[i] * occ[j] * (1.0 - x) ** 2
    return float(0.5 * penalty / total) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    elements = [t.get('element') for t in sites]
    counts = {}
    for i in range(n):
        counts[elements[i]] = counts.get(elements[i], 0.0) + occ[i]
    total_atoms = sum(occ)
    if total_atoms <= 0:
        return 0.0
    expected = 1.0 - sum((v / total_atoms) ** 2 for v in counts.values())
    nearest = [inf for i in range(n)]
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    unlike = 0.0
    total = 0.0
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0 < d <= 1.5 * nearest[i] and nearest[i] < inf:
            w = occ[i] * occ[j] * exp(1.0 - (d / nearest[i]) ** 6)
            total += w
            if elements[i] != elements[j]:
                unlike += w
    return float(unlike / total - expected) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    covalent = ('H', 'B', 'C', 'N', 'O', 'F', 'Si', 'P', 'S', 'Cl', 'Ge', 'As', 'Se', 'Br', 'Sb', 'Te', 'I')
    n = len(sites)
    elements = [t.get('element') for t in sites]
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    radii = []
    for t in sites:
        p = props.get(t.get('element')) or {}
        radii.append(max(0.1, p.get('covalent_radius_A') or p.get('atomic_radius_A') or 1.4))
    total = sum(occ)
    bonds = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and elements[i] == elements[j] and elements[i] in covalent:
            x = d / (radii[i] + radii[j])
            if x <= 1.5:
                bonds += occ[i] * occ[j] * exp(-(x ** 6))
    return float(0.5 * bonds / total) if total > 0 else 0.0

def feature(s):
    s = s or {}
    props = s.get('element_properties') or {}
    occupied = 0.0
    electrons = 0.0
    for t in s.get('sites') or []:
        o = max(0.0, float(t.get('occupancy', 1.0) or 0.0))
        occupied += o
        v = (props.get(t.get('element')) or {}).get('valence_electrons')
        if v is not None:
            electrons += o * max(0.0, v)
    volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
    if volume <= 0:
        volume = (s.get('volume_per_atom_A3') or 0.0) * occupied
    return float(electrons / volume) if volume > 0 else 0.0

